contracts.obligation:
let mut recv = MemoryRegionArray::<64>::new();
let _ = recv.push(MemoryRegion::new(0usize, 4097usize, MemoryRegionType::Usable)).unwrap();
let _ = recv.push(MemoryRegion::new(4095usize, 4098usize, MemoryRegionType::Usable)).unwrap();
let ghost r0 = recv@[0];
let ghost r1 = recv@[1];
let _ = recv.push(MemoryRegion::new(8192usize, 20480usize, MemoryRegionType::Usable)).unwrap();
assert(recv@[0] == r0 && recv@[1] == r1);

let mut recv = MemoryRegionArray::<1>::new();
let _ = recv.push(MemoryRegion::new(0usize, 4097usize, MemoryRegionType::Usable)).unwrap();
let ghost before = recv@;
let res = recv.push(MemoryRegion::new(4095usize, 4098usize, MemoryRegionType::Usable));
assert(res.is_err());
assert(recv@ == before);

broadcast use crate::cpu::axiom_cpu_count_bounds;
let cpu0 = CpuId::try_from(0usize).unwrap();
let mut recv = CpuSet::new_empty();
recv.add(cpu0);
assert(recv@.contains(0));
assert(!recv@.contains(1));

broadcast use crate::cpu::axiom_cpu_count_bounds;
