let mut buf = [0u8; 8];
proof_decl! { let tracked mut owner: crate::specs::mm::io::VmIoOwner; }
#[verus_spec(with => Tracked(owner))]
let mut recv = VmWriter::from(&mut buf[..]);
let r = recv.limit(0);
let ghost cursor = r.cursor;
let ghost end = r.end;
let ghost gid = r.ghost_id;
let val = 0u64;
#[verus_spec(with Tracked(&mut owner))]
let res = r.write_once(&val);
assert(res.is_err());
assert(r.cursor == cursor && r.end == end && r.ghost_id == gid);

